package com.maggie.app.ui.screens.finance

import java.text.Normalizer

/** [name] is the value of `Category.icon`. */
internal data class CategoryIconEntry(
    val name: String,
    val label: String,
    val keywords: List<String>,
)

/** What the picker shows for one icon. */
internal data class CategoryIconTile(val name: String, val label: String)

/**
 * Every Material icon available on both clients (generated by `task icons:generate` from
 * `design/category-icons.json`, which the admin's catalogue is generated from too), the curated
 * ones first with their French label and search words.
 */
internal object CategoryIconCatalog {
    val entries: List<CategoryIconEntry> =
        CategoryIconData.rows.map { CategoryIconEntry(it.name, it.label, it.keywords) }

    private val byName: Map<String, CategoryIconEntry> = entries.associateBy { it.name }

    private class Indexed(val entry: CategoryIconEntry) {
        val label = normalize(entry.label)
        val keywords = entry.keywords.joinToString(" | ") { normalize(it) }
        val name = normalize(entry.name)
    }

    private val index: List<Indexed> by lazy { entries.map(::Indexed) }

    fun find(name: String?): CategoryIconEntry? = byName[name?.trim()?.lowercase().orEmpty()]

    private val accents = Regex("\\p{Mn}+")
    private val separators = Regex("[-_]+")

    /** Lower case, no accents, « œ » as « oe », dashes and underscores as spaces: « Épargne » and « epargne » are one word. */
    fun normalize(text: String): String =
        Normalizer.normalize(text, Normalizer.Form.NFD)
            .replace(accents, "")
            .replace("œ", "oe")
            .replace("Œ", "oe")
            .replace(separators, " ")
            .lowercase()
            .trim()

    /** 0 = label starts with the word, 1 = label contains it, 2 = a keyword does, 3 = the English name does; null = no match. */
    private fun rank(item: Indexed, words: List<String>): Int? {
        var worst = 0
        for (word in words) {
            val best = when {
                item.label.startsWith(word) -> 0
                item.label.contains(word) -> 1
                item.keywords.contains(word) -> 2
                item.name.contains(word) -> 3
                else -> return null
            }
            if (best > worst) worst = best
        }
        return worst
    }

    /**
     * The icons whose label, French keywords or English name contain every word of the query,
     * best matches first (catalogue order within a rank); all of them for a blank query.
     */
    fun filter(query: String): List<CategoryIconEntry> {
        val words = normalize(query).split(' ').filter { it.isNotEmpty() }
        if (words.isEmpty()) return entries
        return index
            .mapNotNull { item -> rank(item, words)?.let { item.entry to it } }
            .sortedBy { it.second }
            .map { it.first }
    }

    /**
     * What the picker lists for [query]: the matching icons, preceded by [current] when it is
     * a name outside the catalogue (kept, shown selected, never silently lost).
     */
    fun tiles(query: String, current: String?): List<CategoryIconTile> {
        val found = filter(query).map { CategoryIconTile(it.name, it.label) }
        val name = current?.trim().orEmpty()
        val unknownShown = name.isNotEmpty() && find(name) == null &&
            (query.isBlank() || normalize(name).contains(normalize(query)))
        return if (unknownShown) listOf(CategoryIconTile(name, name)) + found else found
    }
}
